"""
Outgoing TriMul (AlphaFold3) - Optimized with heuristic per-size dispatch.

CUDA warp-level LayerNorm → Triton 5-way proj+gate+mask → baddbmm →
Triton fused tail LN+gate+linear, with per-problem-size config dispatch.
"""
from typing import Tuple, Dict
import os

import torch
import triton
import triton.language as tl


# ----------------------------------------------------------------------
# CUDA inline extension for warp-level LN
# ----------------------------------------------------------------------
_CUDA_EXT = None

def _get_cuda_ext():
    global _CUDA_EXT
    if _CUDA_EXT is not None:
        return _CUDA_EXT

    os.environ.setdefault("TORCH_CUDA_ARCH_LIST", "8.0")
    os.environ.setdefault("MAX_JOBS", "4")

    from torch.utils.cpp_extension import load_inline

    cpp_src = r"""
#include <torch/extension.h>
torch::Tensor warp_layernorm_fp16_cuda(
    torch::Tensor x, torch::Tensor w, torch::Tensor b, int64_t rows, int cols);
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("warp_layernorm_fp16", &warp_layernorm_fp16_cuda, "warp LN fp16");
}
"""

    cuda_src = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

namespace {

constexpr float kEps = 1e-5f;

__device__ __forceinline__ float warp_sum(float v) {
    v += __shfl_down_sync(0xffffffff, v, 16);
    v += __shfl_down_sync(0xffffffff, v, 8);
    v += __shfl_down_sync(0xffffffff, v, 4);
    v += __shfl_down_sync(0xffffffff, v, 2);
    v += __shfl_down_sync(0xffffffff, v, 1);
    return v;
}

template <int COLS>
__global__ void ln_warp_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    __half* __restrict__ y,
    int64_t rows)
{
    constexpr int kValsPerLane = (COLS + 31) / 32;
    const int warps = static_cast<int>(blockDim.x >> 5);
    const int warp = static_cast<int>(threadIdx.x >> 5);
    const int lane = static_cast<int>(threadIdx.x & 31);
    const int64_t row = static_cast<int64_t>(blockIdx.x) * warps + warp;
    if (row >= rows) return;

    const float* row_x = x + row * static_cast<int64_t>(COLS);
    float vals[kValsPerLane];
    float sum = 0.0f, sumsq = 0.0f;

    #pragma unroll
    for (int t = 0; t < kValsPerLane; ++t) {
        const int c = lane + (t << 5);
        if (c < COLS) {
            const float v = row_x[c];
            vals[t] = v;
            sum += v;
            sumsq = fmaf(v, v, sumsq);
        } else {
            vals[t] = 0.0f;
        }
    }

    sum = warp_sum(sum);
    sumsq = warp_sum(sumsq);
    const float mean = __shfl_sync(0xffffffff, sum, 0) * (1.0f / static_cast<float>(COLS));
    float var = __shfl_sync(0xffffffff, sumsq, 0) * (1.0f / static_cast<float>(COLS)) - mean * mean;
    var = var < 0.0f ? 0.0f : var;
    const float inv_std = rsqrtf(var + kEps);

    __half* row_y = y + row * static_cast<int64_t>(COLS);
    #pragma unroll
    for (int t = 0; t < kValsPerLane; ++t) {
        const int c = lane + (t << 5);
        if (c < COLS) {
            const float nv = (vals[t] - mean) * inv_std;
            const float fv = fmaf(nv, w[c], b[c]);
            row_y[c] = __float2half_rn(fv);
        }
    }
}

__global__ void ln_warp_generic_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    __half* __restrict__ y,
    int64_t rows, int cols)
{
    const int warps = static_cast<int>(blockDim.x >> 5);
    const int warp = static_cast<int>(threadIdx.x >> 5);
    const int lane = static_cast<int>(threadIdx.x & 31);
    const int64_t row = static_cast<int64_t>(blockIdx.x) * warps + warp;
    if (row >= rows) return;

    const float* row_x = x + row * static_cast<int64_t>(cols);
    float sum = 0.0f, sumsq = 0.0f;
    for (int c = lane; c < cols; c += 32) {
        const float v = row_x[c];
        sum += v;
        sumsq = fmaf(v, v, sumsq);
    }
    sum = warp_sum(sum);
    sumsq = warp_sum(sumsq);
    const float mean = __shfl_sync(0xffffffff, sum, 0) * (1.0f / static_cast<float>(cols));
    float var = __shfl_sync(0xffffffff, sumsq, 0) * (1.0f / static_cast<float>(cols)) - mean * mean;
    var = var < 0.0f ? 0.0f : var;
    const float inv_std = rsqrtf(var + kEps);

    __half* row_y = y + row * static_cast<int64_t>(cols);
    for (int c = lane; c < cols; c += 32) {
        const float v = row_x[c];
        const float nv = (v - mean) * inv_std;
        const float fv = fmaf(nv, w[c], b[c]);
        row_y[c] = __float2half_rn(fv);
    }
}

} // anonymous namespace

torch::Tensor warp_layernorm_fp16_cuda(
    torch::Tensor x, torch::Tensor w, torch::Tensor b, int64_t rows, int cols)
{
    TORCH_CHECK(x.is_cuda() && x.scalar_type() == torch::kFloat32);
    auto opts = x.options().dtype(torch::kFloat16);
    auto y = torch::empty({rows, cols}, opts);

    const int warps = 32;
    const int threads = warps * 32;
    const int blocks = static_cast<int>((rows + warps - 1) / warps);

    if (cols == 128) {
        ln_warp_kernel<128><<<blocks, threads>>>(
            x.data_ptr<float>(), w.data_ptr<float>(), b.data_ptr<float>(),
            reinterpret_cast<__half*>(y.data_ptr<at::Half>()), rows);
    } else if (cols == 384) {
        ln_warp_kernel<384><<<blocks, threads>>>(
            x.data_ptr<float>(), w.data_ptr<float>(), b.data_ptr<float>(),
            reinterpret_cast<__half*>(y.data_ptr<at::Half>()), rows);
    } else {
        ln_warp_generic_kernel<<<blocks, threads>>>(
            x.data_ptr<float>(), w.data_ptr<float>(), b.data_ptr<float>(),
            reinterpret_cast<__half*>(y.data_ptr<at::Half>()), rows, cols);
    }
    return y;
}
"""

    _CUDA_EXT = load_inline(
        name="warp_ln_fp16",
        cpp_sources=cpp_src,
        cuda_sources=cuda_src,
        functions=None,
        with_cuda=True,
        extra_cflags=["-O3", "-std=c++17"],
        extra_cuda_cflags=["-O3", "-std=c++17", "-arch=sm_80", "--use_fast_math"],
        verbose=False,
    )
    return _CUDA_EXT


# ----------------------------------------------------------------------
# Triton proj+gate+mask kernel (plain @triton.jit)
# ----------------------------------------------------------------------
@triton.jit
def _proj_gate_mask_kernel(
    x_ptr, mask_ptr,
    left_proj_w_ptr, left_gate_w_ptr,
    right_proj_w_ptr, right_gate_w_ptr,
    out_gate_w_ptr,
    left_ptr, right_ptr, out_gate_ptr,
    M, N, C: tl.constexpr, H: tl.constexpr,
    BLOCK_M: tl.constexpr, BLOCK_H: tl.constexpr, BLOCK_K: tl.constexpr,
    MASKED: tl.constexpr,
):
    pid_m = tl.program_id(0)
    pid_h = tl.program_id(1)
    row_start = pid_m * BLOCK_M
    hid_start = pid_h * BLOCK_H
    rows = row_start + tl.arange(0, BLOCK_M)
    hids = hid_start + tl.arange(0, BLOCK_H)
    row_mask = rows < M
    hid_mask = hids < H

    if MASKED:
        mask_val = tl.load(mask_ptr + rows, mask=row_mask, other=0.0).to(tl.float32)
    else:
        mask_val = tl.full([BLOCK_M], 1.0, dtype=tl.float32)

    acc_lp = tl.zeros((BLOCK_M, BLOCK_H), dtype=tl.float32)
    acc_lg = tl.zeros((BLOCK_M, BLOCK_H), dtype=tl.float32)
    acc_rp = tl.zeros((BLOCK_M, BLOCK_H), dtype=tl.float32)
    acc_rg = tl.zeros((BLOCK_M, BLOCK_H), dtype=tl.float32)
    acc_og = tl.zeros((BLOCK_M, BLOCK_H), dtype=tl.float32)

    for k in range(0, C, BLOCK_K):
        cur_k = k + tl.arange(0, BLOCK_K)
        k_mask = cur_k < C
        a = tl.load(x_ptr + rows[:, None] * C + cur_k[None, :], mask=row_mask[:, None] & k_mask[None, :], other=0.0)
        w_lp = tl.load(left_proj_w_ptr + cur_k[:, None] * H + hids[None, :], mask=k_mask[:, None] & hid_mask[None, :], other=0.0)
        w_lg = tl.load(left_gate_w_ptr + cur_k[:, None] * H + hids[None, :], mask=k_mask[:, None] & hid_mask[None, :], other=0.0)
        w_rp = tl.load(right_proj_w_ptr + cur_k[:, None] * H + hids[None, :], mask=k_mask[:, None] & hid_mask[None, :], other=0.0)
        w_rg = tl.load(right_gate_w_ptr + cur_k[:, None] * H + hids[None, :], mask=k_mask[:, None] & hid_mask[None, :], other=0.0)
        w_og = tl.load(out_gate_w_ptr + cur_k[:, None] * H + hids[None, :], mask=k_mask[:, None] & hid_mask[None, :], other=0.0)
        acc_lp += tl.dot(a, w_lp)
        acc_lg += tl.dot(a, w_lg)
        acc_rp += tl.dot(a, w_rp)
        acc_rg += tl.dot(a, w_rg)
        acc_og += tl.dot(a, w_og)

    left_gate  = 1.0 / (1.0 + tl.exp(-acc_lg))
    right_gate = 1.0 / (1.0 + tl.exp(-acc_rg))
    out_gate   = 1.0 / (1.0 + tl.exp(-acc_og))
    left_out  = acc_lp * left_gate * mask_val[:, None]
    right_out = acc_rp * right_gate * mask_val[:, None]

    # [B, HD, N, N] layout offset
    N_sq = N * N
    b_idx = rows // N_sq
    rem   = rows - b_idx * N_sq
    i_idx = rem // N
    k_idx = rem - i_idx * N
    bhd_offset = ((b_idx[:, None] * H + hids[None, :]) * N_sq) + i_idx[:, None] * N + k_idx[:, None]

    tl.store(left_ptr + bhd_offset, left_out.to(tl.float16), mask=row_mask[:, None] & hid_mask[None, :])
    tl.store(right_ptr + bhd_offset, right_out.to(tl.float16), mask=row_mask[:, None] & hid_mask[None, :])
    tl.store(out_gate_ptr + bhd_offset, out_gate.to(tl.float16), mask=row_mask[:, None] & hid_mask[None, :])


# ----------------------------------------------------------------------
# Triton tail kernel (plain @triton.jit)
# ----------------------------------------------------------------------
@triton.jit
def _ln_gate_out_linear_fused_kernel(
    hidden_ptr, out_gate_ptr,
    ln_w_ptr, ln_b_ptr, w_out_ptr, out_ptr,
    B, N, H: tl.constexpr, D: tl.constexpr,
    eps: tl.constexpr,
    BLOCK_M: tl.constexpr, BLOCK_H: tl.constexpr, BLOCK_D: tl.constexpr,
):
    pid = tl.program_id(0)
    row_start = pid * BLOCK_M
    rows = row_start + tl.arange(0, BLOCK_M)
    row_mask = rows < (B * N * N)
    N_sq = N * N
    b_idx = rows // N_sq
    rem = rows - b_idx * N_sq
    i_idx = rem // N
    j_idx = rem - i_idx * N
    hids = tl.arange(0, BLOCK_H)
    hid_mask = hids < H
    bhd_offset = ((b_idx[:, None] * H + hids[None, :]) * N_sq) + i_idx[:, None] * N + j_idx[:, None]
    hidden_tile = tl.load(hidden_ptr + bhd_offset, mask=row_mask[:, None] & hid_mask[None, :], other=0.0)
    out_gate_tile = tl.load(out_gate_ptr + bhd_offset, mask=row_mask[:, None] & hid_mask[None, :], other=0.0)
    hidden_fp32 = hidden_tile.to(tl.float32)
    sum_val = tl.sum(hidden_fp32, axis=1)
    sumsq_val = tl.sum(hidden_fp32 * hidden_fp32, axis=1)
    mean = sum_val / H
    var = sumsq_val / H - mean * mean
    inv_std = 1.0 / tl.sqrt(var + eps)
    w_ln = tl.load(ln_w_ptr + hids, mask=hid_mask, other=0.0)
    b_ln = tl.load(ln_b_ptr + hids, mask=hid_mask, other=0.0)
    hidden_norm = (hidden_fp32 - mean[:, None]) * inv_std[:, None]
    hidden_norm = hidden_norm * w_ln[None, :] + b_ln[None, :]
    out_gate_fp32 = out_gate_tile.to(tl.float32)
    gated = hidden_norm * out_gate_fp32
    gated_fp16 = gated.to(tl.float16)
    for d0 in range(0, D, BLOCK_D):
        cols = d0 + tl.arange(0, BLOCK_D)
        col_mask = cols < D
        w_out = tl.load(w_out_ptr + hids[:, None] * D + cols[None, :], mask=hid_mask[:, None] & col_mask[None, :], other=0.0)
        out = tl.dot(gated_fp16, w_out)
        tl.store(out_ptr + rows[:, None] * D + cols[None, :], out, mask=row_mask[:, None] & col_mask[None, :])


def _get_w16_T(weights, name, ref):
    key = name + "_T_fp16"
    w = weights.get(key, None)
    if w is None or w.device != ref.device:
        w0 = weights[name]
        if w0.dtype != torch.float16 or w0.device != ref.device:
            w0 = w0.to(device=ref.device, dtype=torch.float16)
        w = w0.t().contiguous()
        weights[key] = w
    return w


_scratch = {}


def custom_kernel(data):
    inp, mask, weights, cfg = data
    dim = cfg["dim"]
    hidden_dim = cfg["hidden_dim"]
    nomask = cfg.get("nomask", True)

    device = inp.device
    B, N, _, _ = inp.shape
    M = B * N * N

    torch.backends.cuda.matmul.allow_fp16_reduced_precision_reduction = True

    # 1) CUDA warp-level LN (fp16 output)
    try:
        ext = _get_cuda_ext()
        x_flat = inp.view(M, dim).contiguous()
        x_norm_flat = ext.warp_layernorm_fp16(
            x_flat, weights["norm.weight"], weights["norm.bias"], M, dim
        )
        x_norm = x_norm_flat.view(B, N, N, dim)
    except Exception:
        x_norm = torch.nn.functional.layer_norm(
            inp, [dim], weights["norm.weight"], weights["norm.bias"]
        ).to(torch.float16)

    # 2) Prepare weights
    left_proj_w_T  = _get_w16_T(weights, "left_proj.weight", inp)
    right_proj_w_T = _get_w16_T(weights, "right_proj.weight", inp)
    left_gate_w_T  = _get_w16_T(weights, "left_gate.weight", inp)
    right_gate_w_T = _get_w16_T(weights, "right_gate.weight", inp)
    out_gate_w_T   = _get_w16_T(weights, "out_gate.weight", inp)

    # 3) Mask
    if not nomask and mask is not None:
        mask_flat = mask.reshape(M).to(torch.float16).contiguous()
        MASKED = 1
    else:
        mask_flat = torch.empty(0, dtype=torch.float16, device=device)
        MASKED = 0

    # 4) Buffers - out_gate in [B, HD, N, N] format
    skey = (B, N, dim, hidden_dim, device)
    buf = _scratch.get(skey, None)
    if buf is None:
        buf = {
            "left": torch.empty((B, hidden_dim, N, N), dtype=torch.float16, device=device),
            "right": torch.empty((B, hidden_dim, N, N), dtype=torch.float16, device=device),
            "out_gate": torch.empty((B, hidden_dim, N, N), dtype=torch.float16, device=device),
            "out_bmm": torch.empty((B * hidden_dim, N, N), dtype=torch.float16, device=device),
            "out": torch.empty((B, N, N, dim), dtype=torch.float32, device=device),
        }
        _scratch[skey] = buf

    left = buf["left"]
    right = buf["right"]
    out_gate = buf["out_gate"]

    # 5) Fused proj+gate+mask - per-dim config dispatch
    p_bm, p_bh, p_bk, p_nw, p_ns = 64, 64, 32, 4, 3
    grid_proj = (triton.cdiv(M, p_bm), triton.cdiv(hidden_dim, p_bh))
    _proj_gate_mask_kernel[grid_proj](
        x_norm, mask_flat,
        left_proj_w_T, left_gate_w_T, right_proj_w_T, right_gate_w_T, out_gate_w_T,
        left, right, out_gate,
        M, N, dim, hidden_dim,
        BLOCK_M=p_bm, BLOCK_H=p_bh, BLOCK_K=p_bk,
        MASKED=MASKED, num_warps=p_nw, num_stages=p_ns,
    )

    # 6) bmm
    left_mat = left.view(B * hidden_dim, N, N)
    right_mat = right.view(B * hidden_dim, N, N).transpose(1, 2)
    out_bmm = buf["out_bmm"]
    torch.baddbmm(out_bmm, left_mat, right_mat, beta=0.0, alpha=1.0, out=out_bmm)
    hidden = out_bmm.view(B, hidden_dim, N, N)

    # 7) Fused tail - per-N config dispatch
    t_bm = 128 if N <= 256 else 64
    t_bh, t_bd, t_nw, t_ns = 128, 64, 4, 3
    to_out_w_T = _get_w16_T(weights, "to_out.weight", inp)
    out = buf["out"]
    grid_out = (triton.cdiv(B * N * N, t_bm),)
    _ln_gate_out_linear_fused_kernel[grid_out](
        hidden.view(-1), out_gate.view(-1),
        weights["to_out_norm.weight"], weights["to_out_norm.bias"],
        to_out_w_T, out,
        B, N, hidden_dim, dim, 1e-5,
        BLOCK_M=t_bm, BLOCK_H=t_bh, BLOCK_D=t_bd,
        num_warps=t_nw, num_stages=t_ns,
    )

    return out
